-- Phase 1 public sample catalog and customer-owned recovery journeys.
-- Costs, margins, stock counts and supplier references are deliberately excluded.
alter table public.products drop constraint if exists products_price_check;
alter table public.products drop constraint if exists products_rental7_check;
alter table public.products drop constraint if exists products_rental30_check;
alter table public.products add column if not exists rental_daily integer not null default 0;
alter table public.products add column if not exists kind text not null default 'product';
alter table public.products add column if not exists unit text not null default 'each';
alter table public.products add constraint products_sample_rates check(price>=0 and rental7>=0 and rental30>=0 and rental_daily>=0 and kind in ('product','service'));
insert into public.products(id,name,price,rental7,rental30,rental_daily,kind,unit,deposit,active)
select x->>'id',x->>'name',(x->>'price')::int,(x->>'rental7')::int,(x->>'rental30')::int,(x->>'rentalDaily')::int,x->>'kind',x->>'unit',0,true
