alter table public.recovery_templates enable row level security;
revoke all on public.recovery_templates from anon,authenticated;
grant select on public.recovery_templates to anon,authenticated;
create policy templates_public_read on public.recovery_templates for select using(true);
create table public.recovery_plans (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 order_id uuid not null references public.orders(id) on delete cascade,package_slug text not null references public.recovery_templates(slug),name text not null,
 status text not null default 'submitted' check(status in ('submitted','reviewed','scheduled','recovering','collection','completed','cancelled')),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),events jsonb not null default '[]',unique(order_id,package_slug)
);
create index recovery_plans_user_created on public.recovery_plans(user_id,created_at desc);
alter table public.recovery_plans enable row level security;
revoke all on public.recovery_plans from public,anon,authenticated;
grant select on public.recovery_plans to authenticated;
create policy recovery_plans_own_read on public.recovery_plans for select to authenticated using((select auth.uid())=user_id);
-- Only trusted database operators can advance statuses. Customers have read-only access.
create function public.record_recovery_status() returns trigger language plpgsql set search_path='' as $$
declare stages text[]:=array['submitted','reviewed','scheduled','recovering','collection','completed'];
begin
 if tg_op='INSERT' then
  new.status:='submitted';new.events:=jsonb_build_array(jsonb_build_object('status','submitted','at',now(),'note','Demo selections saved. Awaiting coordinator review.'));
 else
  if new.user_id<>old.user_id or new.order_id<>old.order_id or new.package_slug<>old.package_slug then raise exception 'Recovery plan ownership is immutable';end if;
  if new.status is distinct from old.status then
   if old.status in ('completed','cancelled') or (new.status<>'cancelled' and array_position(stages,new.status) is distinct from array_position(stages,old.status)+1) then raise exception 'Invalid recovery status transition';end if;
   new.events:=old.events||jsonb_build_array(jsonb_build_object('status',new.status,'at',now(),'note','Status updated by the care team.'));
  else new.events:=old.events;end if;
 end if;
 new.updated_at:=now();return new;
end;$$;
create trigger recovery_status_history before insert or update on public.recovery_plans for each row execute function public.record_recovery_status();
revoke all on function public.record_recovery_status() from public,anon,authenticated;

create or replace function public.place_demo_order(p_lines jsonb,p_address jsonb,p_rental_start date,p_request_key uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); item jsonb; product public.products; qty integer; days integer; mode text;
 unit_price integer; item_deposit integer; sub integer:=0; dep integer:=0; snapshot jsonb:='[]'; result public.orders;
begin
 if uid is null then raise exception 'Sign in required';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 select * into result from public.orders where user_id=uid and request_key=p_request_key;
 if found then return to_jsonb(result)-'user_id'-'request_key';end if;
 if p_request_key is null or jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines)<1 or jsonb_array_length(p_lines)>100 then raise exception 'Invalid cart';end if;
 if jsonb_typeof(p_address) is distinct from 'object' or length(coalesce(p_address->>'name','')) not between 2 and 80
 or coalesce(p_address->>'phone','') !~ '^\+?[0-9 ()-]{7,20}$' or length(coalesce(p_address->>'address','')) not between 8 and 300
 or length(coalesce(p_address->>'city','')) not between 2 and 80 or coalesce(p_address->>'pincode','') !~ '^[0-9]{6}$' then raise exception 'Invalid address';end if;
 if (select count(*) from public.orders where user_id=uid and created_at>now()-interval '1 hour')>=30 then raise exception 'Too many orders';end if;
 for item in select * from jsonb_array_elements(p_lines) loop
  select * into product from public.products where id=item->>'productId' and active;
  if not found then raise exception 'Product unavailable';end if;
  if coalesce(item->>'quantity','') !~ '^[0-9]+$' or coalesce(item->>'days','') !~ '^[0-9]+$' then raise exception 'Invalid quantity';end if;
  qty:=(item->>'quantity')::integer;days:=(item->>'days')::integer;mode:=item->>'mode';
  if qty not between 1 and 60 or days not between 1 and 90 or mode is null or mode not in ('purchase','rental','service') then raise exception 'Invalid cart line';end if;
  if mode='rental' and (p_rental_start is null or p_rental_start<current_date) then raise exception 'Invalid rental date';end if;
  if (mode='service' and product.kind<>'service') or (mode<>'service' and product.kind='service') or (mode='purchase' and product.price<=0) or (mode='rental' and product.rental7<=0) then raise exception 'Unavailable item mode';end if;
  if item ? 'packageSlug' and (jsonb_typeof(item->'packageSlug')<>'string' or not exists(select 1 from public.recovery_templates where slug=item->>'packageSlug')) then raise exception 'Unknown recovery package';end if;
  unit_price:=case when mode<>'rental' then product.price when product.rental_daily>0 then product.rental_daily*days when days=30 then product.rental30 else product.rental7*((days+6)/7) end;
  item_deposit:=case when mode='rental' then product.deposit else 0 end;
  sub:=sub+unit_price*qty;dep:=dep+item_deposit*qty;
  snapshot:=snapshot||jsonb_build_array(jsonb_build_object('productId',product.id,'name',product.name,'mode',mode,'quantity',qty,'days',days,'unitPrice',unit_price,'deposit',item_deposit,'packageSlug',item->>'packageSlug'));
 end loop;
 insert into public.orders(user_id,request_key,subtotal,deposit,total,address,items,rental_start)
 values(uid,p_request_key,sub,dep,sub+dep,jsonb_build_object('name',p_address->>'name','phone',p_address->>'phone','address',p_address->>'address','city',p_address->>'city','pincode',p_address->>'pincode'),snapshot,p_rental_start) returning * into result;
 insert into public.recovery_plans(user_id,order_id,package_slug,name)
 select distinct uid,result.id,t.slug,t.name from jsonb_array_elements(snapshot) x join public.recovery_templates t on t.slug=x->>'packageSlug';
 return to_jsonb(result)-'user_id'-'request_key';
end;$$;
revoke all on function public.place_demo_order(jsonb,jsonb,date,uuid) from public,anon;
grant execute on function public.place_demo_order(jsonb,jsonb,date,uuid) to authenticated;

